// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type CartSummaryProps = Record<string, any>;

const CartSummary: React.FC<CartSummaryProps> = ({
  backgroundColor = "#0485B9",
  transparentBackground = false,
  durationInSeconds = 4, // Increased to 4s to ensure a full 1+ second pause at the end
  cardColor = "#FFFFFF",
  textColor = "#111827",
  promoCode = "SAVE10",
  promoError = "Promo invalid",
  promoButtonColor = "#F3F4F6",
  promoButtonTextColor = "#111827",
  checkoutButtonColor = "#111827",
  checkoutButtonTextColor = "#FFFFFF",
  errorColor = "#EF4444",
}) => {
  const frame = useCurrentFrame();
  const { width, fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings (based on 30fps)
  // 0.0s - 0.5s (0-15f): Card fades and slides up
  // 0.5s - 1.5s (15-45f): Typing promo code
  // 1.5s - 2.0s (45-60f): Button press
  // 2.0s - 2.8s (60-84f): Error message appears with bounce
  // 2.8s - 4.0s (84-120f): 1.2 second pause at the end

  // 1. Card Entry Animation
  const cardOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });
  const cardY = interpolate(frame, [0, 15], [100, 0], {
    extrapolateRight: "clamp",
  });

  // 2. Typing Effect Animation
  const typingProgress = interpolate(frame, [15, 45], [0, promoCode.length], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const typedLength = Math.floor(typingProgress);
  const typedText = promoCode.substring(0, typedLength);
  const showPlaceholder = typedLength === 0;

  // 3. Button Press Animation
  const buttonScale = interpolate(frame, [45, 52, 60], [1, 0.96, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // 4. Error Message Animation (Bouncing & Standing Out)
  const errorOpacity = interpolate(frame, [60, 65], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  
  const errorBounce = spring({
    frame: frame - 60,
    fps,
    config: {
      damping: 7, // Low damping for extra bounce
      stiffness: 180,
      mass: 0.6,
    },
  });

  const errorY = interpolate(errorBounce, [0, 1], [-30, 0]);
  const errorScale = interpolate(errorBounce, [0, 1], [0.3, 1]);

  // Responsive Layout Calculations
  const cardWidth = width * 0.85;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          width: cardWidth,
          backgroundColor: cardColor,
          borderRadius: 48,
          padding: 64,
          display: "flex",
          flexDirection: "column",
          opacity: cardOpacity,
          transform: `translateY(${cardY}px)`,
          boxShadow: "0 20px 40px rgba(0,0,0,0.1)",
          transition: "none",
        }}
      >
        {/* Order Summary Header */}
        <h2
          style={{
            margin: 0,
            marginBottom: 48,
            fontSize: 52,
            fontWeight: 800,
            color: textColor,
            transition: "none",
          }}
        >
          Summary
        </h2>

        {/* Promo Field */}
        <div
          style={{
            width: "100%",
            height: 120,
            border: `3px solid ${promoButtonColor}`,
            borderRadius: 24,
            display: "flex",
            alignItems: "center",
            padding: "0 40px",
            fontSize: 44,
            color: textColor,
            position: "relative",
            transition: "none",
            overflow: "hidden",
          }}
        >
          {showPlaceholder ? (
            <span style={{ color: "#9CA3AF", transition: "none" }}>Promo code</span>
          ) : (
            <span style={{ transition: "none" }}>{typedText}</span>
          )}
          
          {/* Blinking cursor effect during typing phase */}
          {frame >= 15 && frame <= 48 && frame % 15 < 8 && (
            <span
              style={{
                display: "inline-block",
                width: 4,
                height: 50,
                backgroundColor: textColor,
                marginLeft: 8,
                transition: "none",
              }}
            />
          )}
        </div>

        {/* Add Promo Button */}
        <div
          style={{
            marginTop: 32,
            width: "100%",
            height: 110,
            backgroundColor: promoButtonColor,
            borderRadius: 24,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontWeight: 700,
            fontSize: 38,
            color: promoButtonTextColor,
            transform: `scale(${buttonScale})`,
            transformOrigin: "center center",
            transition: "none",
          }}
        >
          Add promo
        </div>

        {/* Error Text Container (fixed height to prevent layout shift) */}
        <div
          style={{
            height: 50,
            marginTop: 20,
            display: "flex",
            alignItems: "center",
            transition: "none",
          }}
        >
          <span
            style={{
              display: "inline-block",
              fontSize: 36,
              fontWeight: 800, // Made bolder to stand out
              color: errorColor,
              opacity: errorOpacity,
              transform: `translateY(${errorY}px) scale(${errorScale})`,
              transformOrigin: "center left",
              transition: "none",
            }}
          >
            {promoError}
          </span>
        </div>

        {/* Divider */}
        <div
          style={{
            width: "100%",
            height: 3,
            backgroundColor: promoButtonColor,
            margin: "32px 0 48px 0",
            transition: "none",
          }}
        />

        {/* Checkout Button */}
        <div
          style={{
            width: "100%",
            height: 140,
            backgroundColor: checkoutButtonColor,
            borderRadius: 32,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontWeight: 800,
            fontSize: 48,
            color: checkoutButtonTextColor,
            transition: "none",
          }}
        >
          Checkout
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CartSummary;